<script setup lang="ts">
import { ref, computed, onMounted } from 'vue';
import { ElMessage } from 'element-plus';
import { api, query } from './api';
const items = ref<any[]>([]), versions = ref<string[]>([]), poolVersion = ref(''), source = ref('HUMAN'), version = ref(''), search = ref(''), category = ref(''), filter = ref('all'), busy = ref(false), error = ref(''), selected = ref<any>(null), attempts = ref<any[]>([]), detailError = ref('');
const dates = ref<[string,string] | null>(null);
const categoryNames: Record<string,string> = {food:'美食',animal:'动物',action:'动作',daily:'日常',travel:'旅行',sport:'运动',childhood:'童年',idiom:'成语',phrases:'常用语',quotes:'经典梗',screen:'影视',music:'音乐',technology:'科技',ai:'智能生活',internet:'网络用语',brand:'品牌',people:'人物',poem:'诗词'};
const categories = computed(() => [...new Set(items.value.flatMap(e => e.categories as string[]))]);
function ratio(n: number, d: number) { return d ? (Number(n) / Number(d) * 100).toFixed(1) + '%' : '—'; }
function seconds(ms: number | null) { return ms === null || ms === undefined ? '—' : (Number(ms)/1000).toFixed(1)+'秒'; }
function needsReview(r:any) { return Number(r.samples)>=20 && (Number(r.correct)/Number(r.samples)<0.2 || Number(r.skipped)/Number(r.samples)>0.6) || Number(r.clear)+Number(r.unclear)>=5 && Number(r.unclear)/(Number(r.clear)+Number(r.unclear))>0.5; }
const rows = computed(() => items.value.filter(r => r.word.includes(search.value) && (!category.value || r.categories.includes(category.value)) && (filter.value==='all' || filter.value==='review' && needsReview(r) || filter.value==='disabled' && !r.enabled || filter.value==='unplayed' && !Number(r.samples))));
function params() { return { source:source.value, version:version.value||undefined, from:dates.value?.[0], to:dates.value?.[1] }; }
let request = 0;
async function load() { const id=++request;busy.value=true;try { const data=await api('/emoji/words'+query(params()));if(id!==request)return;items.value=data.items;versions.value=data.versions;poolVersion.value=data.poolVersion;error.value=''; } catch(e) { if(id===request)error.value=(e as Error).message; } finally { if(id===request)busy.value=false; } }
async function toggle(row:any) { if(busy.value)return;busy.value=true;try { await api('/emoji/pool','POST',{word:row.word,enabled:!row.enabled});ElMessage.success(row.enabled?'已暂停，后续抽词将排除':'已恢复，仍需原词条状态有效');await load(); } catch(e) { ElMessage.error((e as Error).message); } finally { busy.value=false; } }
let detailRequest=0;
async function detail(row:any) { const id=++detailRequest;selected.value=row;attempts.value=[];detailError.value='';try { const data=await api('/emoji/attempts'+query({...params(),version:'ALL',word:row.word}));if(id===detailRequest)attempts.value=data; } catch(e) { if(id===detailRequest)detailError.value=(e as Error).message; } }
onMounted(load);
</script>
<template>
  <main class="emoji-quality">
    <header><div><span class="eyebrow">STICKER PARTY</span><h1>贴纸猜词 · 词池与实战</h1><p>当前词池 {{ items.length }} 词 · {{ poolVersion }}</p></div><el-button :loading="busy" @click="load">刷新</el-button></header>
    <el-alert title="词池经过表达思路筛选，尚未通过真人可猜性验收。默认展示真人与未知来源记录，排除测试和模拟；每词按当前参考组合版本统计。" type="info" :closable="false"/>
    <div class="filters"><el-input v-model="search" placeholder="搜索词语" clearable style="width:210px"/><el-select v-model="category" placeholder="全部题包" clearable style="width:150px"><el-option v-for="code in categories" :key="code" :value="code" :label="categoryNames[code]||code"/></el-select><el-select v-model="filter" style="width:155px"><el-option value="all" label="全部词语"/><el-option value="review" label="建议复核"/><el-option value="disabled" label="已暂停"/><el-option value="unplayed" label="暂无样本"/></el-select><el-select v-model="source" style="width:170px" @change="load"><el-option value="HUMAN" label="真人＋未知来源"/><el-option value="LIVE" label="仅真人 LIVE"/><el-option value="UNKNOWN" label="仅未知来源"/><el-option value="TEST" label="仅测试"/><el-option value="SIMULATION" label="仅模拟"/><el-option value="ALL" label="所有来源（含测试）"/></el-select><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" @change="load"/><el-select v-model="version" style="width:220px" @change="load"><el-option value="" label="当前词池版本"/><el-option value="ALL" label="所有词池版本"/><el-option v-for="v in versions" :key="v" :value="v" :label="v"/></el-select></div>
    <p class="method">默认最近30天。猜对率、跳过率分母为已记录结果的题数；未完成含时间到、主动结束和离线，不能直接当作词太难。耗时扣除暂停，仅均值统计猜对题；“猜对前揭字”不包含最终正确提交一次性点亮的字。“全揭后答对”需结合空题板和猜词人数判断。建议复核：至少20题且猜对率&lt;20%或跳过率&gt;60%，或至少5份评价且多数觉得牵强；仅提示，不自动停用。</p>
    <el-alert v-if="error" :title="error" type="error"/>
    <el-table :data="rows" height="620" border v-loading="busy" row-key="word">
      <el-table-column prop="word" label="词语" min-width="180" fixed><template #default="s"><strong>{{s.row.word}}</strong><div><el-tag v-if="!s.row.enabled" type="info" size="small">已暂停</el-tag><el-tag v-else-if="!s.row.available" type="info" size="small">原词条不可用</el-tag><el-tag v-else-if="needsReview(s.row)" type="warning" size="small">建议复核</el-tag><small v-else-if="Number(s.row.samples)<20">样本不足</small></div></template></el-table-column>
      <el-table-column label="题包" min-width="140"><template #default="s">{{s.row.categories.map((c:string)=>categoryNames[c]||c).join('、')}}</template></el-table-column>
      <el-table-column prop="samples" label="题数" width="75" sortable/><el-table-column prop="games" label="局数" width="75" sortable/>
      <el-table-column label="猜对率" width="100"><template #default="s">{{ratio(s.row.correct,s.row.samples)}}</template></el-table-column><el-table-column label="跳过率" width="100"><template #default="s">{{ratio(s.row.skipped,s.row.samples)}}</template></el-table-column><el-table-column prop="unfinished" label="未完成" width="90"/>
      <el-table-column label="平均猜中耗时" width="135"><template #default="s">{{seconds(s.row.average_solve_ms)}}</template></el-table-column><el-table-column label="猜对前揭字" width="120"><template #default="s">{{s.row.average_hints_before_win==null?'—':Number(s.row.average_hints_before_win).toFixed(1)}}</template></el-table-column><el-table-column prop="fully_revealed_wins" label="全揭后答对" width="115"/><el-table-column prop="blank_boards" label="空题板" width="85"/><el-table-column label="平均猜词人数" width="125"><template #default="s">{{s.row.average_guessers==null?'—':Number(s.row.average_guessers).toFixed(1)}}</template></el-table-column>
      <el-table-column label="看得懂／太牵强" width="145"><template #default="s">{{s.row.clear}} / {{s.row.unclear}}</template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="s"><el-button size="small" @click="detail(s.row)">参考与记录</el-button><el-button size="small" :disabled="busy" @click="toggle(s.row)">{{s.row.enabled?'暂停':'恢复'}}</el-button></template></el-table-column>
    </el-table>
    <el-drawer :model-value="!!selected" :title="selected?.word" size="78%" @close="selected=null;detailRequest++"><template v-if="selected"><p>当前参考版本：{{selected.referenceVersion}}</p><div class="reference-images"><img v-for="(id,i) in selected.referenceEmojis" :key="i" :src="'/emoji/'+id+'.png'" :alt="id"/></div><p>{{selected.referenceExplanation}}</p><p>下方保留所有词池／参考版本的最近100题，沿用上方日期和来源筛选。当前表格的统计只使用当前参考版本。暂无实战记录时不推断难度。</p><el-alert v-if="detailError" :title="detailError" type="error"/><el-table :data="attempts" border><el-table-column prop="completed_at" label="记录时间" min-width="180"/><el-table-column prop="source" label="来源" width="95"/><el-table-column prop="pool_version" label="词池版本" min-width="215"/><el-table-column prop="reference_version" label="参考版本" min-width="220"/><el-table-column prop="end_reason" label="结果／结束原因" min-width="160"/><el-table-column label="有效耗时" width="100"><template #default="s">{{seconds(s.row.active_ms)}}</template></el-table-column><el-table-column prop="guess_count" label="提交数" width="85"/><el-table-column prop="hinted_before_win" label="猜对前揭字" width="120"/><el-table-column prop="revealed_count" label="最终揭字" width="95"/><el-table-column prop="player_count" label="总人数" width="85"/></el-table></template></el-drawer>
  </main>
</template>
<style scoped>
.emoji-quality{padding:32px}.emoji-quality header{display:flex;justify-content:space-between;align-items:center}.filters{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0}.method{font-size:13px;color:#69717d;line-height:1.9;max-width:1250px}.reference-images{display:flex;gap:12px;flex-wrap:wrap}.reference-images img{width:72px;height:72px;object-fit:contain;border:2px solid #484052;border-radius:50%;padding:5px;background:#fff9e8}small{color:#9a8b73}.emoji-quality h1{margin-bottom:10px}
</style>
